srcDoc.css:
body {
  margin: 0;
  font-family: "Open Sans", "Inter", "Segoe UI", Arial, sans-serif;
  color: #e2e8f0;
  background: #0f172a;
}

.page {
  padding: 14px 24px 90px;
  background: #0f172a;
  min-height: 100%;
  box-sizing: border-box;
}

.ptitle {
  font-size: 22px;
  font-weight: 700;
  color: #ffffff;
  margin: 4px 0 2px;
}

.sub {
  font-size: 13px;
  color: #94a3b8;
  margin-bottom: 6px;
}

.month {
  margin-top: 26px;
}

.mhead {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px solid #334155;
  padding-bottom: 8px;
  margin-bottom: 2px;
}

.mname {
  font-size: 18px;
  font-weight: 700;
  color: #ffffff;
}

.mtotal {
  font-size: 15px;
  color: #cbd5e1;
  font-weight: 600;
}

.ptbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.ptbl th {
  text-align: left;
  color: #cbd5e1;
  font-weight: 700;
  font-size: 15px;
  padding: 12px 16px;
  border-bottom: 1px solid #334155;
}

.ptbl td {
  padding: 14px 16px;
  color: #e2e8f0;
  border: 0;
}

.ptbl tbody tr:nth-child(odd) td {
  background: #1e293b;
}

.ptbl tbody tr:nth-child(even) td {
  background: #0f172a;
}

.r {
  text-align: right;
}

.dlcol {
  text-align: right !important;
}

th.r {
  text-align: right;
}

.dlcol {
  text-align: right;
}

.qty {
  color: #60a5fa;
  text-decoration: underline;
  cursor: pointer;
  font-weight: 600;
}

.qty:hover {
  color: #93c5fd;
}

.dl {
  padding: 8px 10px;
  border: 1px solid #334155;
  border-radius: 4px;
  background: #1e293b;
  color: #ffffff;
  font-size: 13px;
  min-width: 250px;
  cursor: pointer;
  outline: none;
}

.dl:focus {
  border-color: #64748b;
}

.sentinel {
  padding: 18px;
  text-align: center;
  color: #94a3b8;
  font-size: 13px;
  min-height: 20px;
}

.err {
  padding: 16px;
  text-align: center;
  color: #f87171;
  font-size: 13px;
}

.empty {
  padding: 40px;
  text-align: center;
  color: #64748b;
  font-style: italic;
}

.overlay {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 23, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal {
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 8px;
  width: min(1000px, 92vw);
  max-height: 86vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
}

.mtop {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px 10px;
}

.mtitle {
  font-size: 20px;
  font-weight: 700;
  color: #ffffff;
}

.x {
  font-size: 26px;
  color: #94a3b8;
  cursor: pointer;
  line-height: 1;
}

.x:hover {
  color: #ffffff;
}

.mbody {
  padding: 6px 24px;
  overflow: auto;
}

.scrollx {
  overflow-x: auto;
}

.dtbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.dtbl th {
  text-align: left;
  color: #cbd5e1;
  font-weight: 700;
  padding: 10px 14px;
  border-bottom: 1px solid #334155;
  white-space: nowrap;
}

.dtbl td {
  padding: 10px 14px;
  color: #e2e8f0;
  white-space: nowrap;
}

.dtbl tbody tr:nth-child(odd) td {
  background: #1e293b;
}

.dtbl tbody tr:nth-child(even) td {
  background: #0f172a;
}

.loading {
  padding: 24px;
  text-align: center;
  color: #94a3b8;
}

.mfoot {
  padding: 14px 24px 20px;
  text-align: center;
  border-top: 1px solid #334155;
}

.okbtn {
  background: #2952cc;
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 10px 28px;
  font-size: 15px;
  cursor: pointer;
}

.okbtn:hover {
  background: #1f43ad;
}

